L["0 keeps it up until you close it."] = "0 lo tiene aperto finché non lo chiudi."
L["1 %s is worth %g to %s."] = "1 %s vale %g per %s."
L["1 book"] = "1 libro"
L["1 consumable"] = "1 consumabile"
L["1 consumable watched"] = "1 consumabile monitorato"
L["1 craft"] = "1 creazione"
L["1 day"] = "1 giorno"
L["1 dungeon"] = "1 spedizione"
L["1 hour"] = "1 ora"
L["1 in %d"] = "1 su %d"
L["1 item on the bar"] = "1 oggetto sulla barra"
L["1 minute"] = "1 minuto"
L["1 paladin in your group"] = "1 paladino nel tuo gruppo"
L["1 player has their own blessing"] = "1 giocatore ha la propria benedizione"
L["1 profile on this account"] = "1 profilo su questo account"
L["1 raid"] = "1 incursione"
L["1 runs Naowh Forever"] = "1 usa Naowh Forever"
L["1 setting changed from its default"] = "1 impostazione diversa dal valore predefinito"
L["1 spell"] = "1 incantesimo"
L["1 Unspent Talent Point"] = "1 punto talento non speso"
L["1. PICK YOUR BARS"] = "1. SCEGLI LE BARRE"
L["100%  (default)"] = "100%  (predefinito)"
L["100%, native resolution"] = "100%, risoluzione nativa"
L["12-hour clock"] = "Orologio a 12 ore"
L["16x Anisotropic"] = "Anisotropico 16x"
L["2. ALSO KEEP"] = "2. TIENI ANCHE"
L["24-Hour Clock"] = "Orologio a 24 ore"
L["24-hour clock"] = "Orologio a 24 ore"
L["3. NAME AND SAVE"] = "3. DAI UN NOME E SALVA"
L["30, while the game is not in focus"] = "30, quando il gioco non è in primo piano"
L[": copy ID or Wowhead link"] = ": copia ID o link Wowhead"
L[": mail expiring soon on "] = ": posta in scadenza su "
L["; buys at vendors"] = "; compra dai mercanti"
L["<AFK>"] = "<AFK>"
L["<DND>"] = "<ND>"
L["[Where?]"] = "[Dove?]"
L["A /thank to everyone around you when the game cannot name the caster."] = "Un /thank a tutti quelli intorno quando il gioco non sa dire chi ha lanciato."
L["A [Where?] link after a whisper from someone whose zone is not known. Clicking it runs a /who for them and prints their zone; their next messages are tagged."] = "Un link [Dove?] dopo un sussurro di qualcuno di cui non si conosce la zona. Cliccandolo esegue un /who e stampa la sua zona; i suoi messaggi successivi vengono contrassegnati."
L["A banner and a sound when one of them joins your group."] = "Un banner e un suono quando uno di loro entra nel tuo gruppo."
L["A bar at the threat where you would pull aggro, so the gap to it is easy to read."] = "Una barra alla minaccia a cui prenderesti l'aggro, così la distanza è facile da leggere."
L["A bar for your target's swings, restarted by each physical hit you take while it is targeting you, and shortened when it parries. It is an estimate: the game does not say who hit you or with what, so other attackers, physical specials and bleed ticks restart it too."] = "Una barra per i colpi del tuo bersaglio, riavviata da ogni colpo fisico che subisci mentre ti ha come bersaglio e accorciata quando para. È una stima: il gioco non dice chi ti ha colpito né con cosa, quindi anche altri attaccanti, attacchi fisici speciali e tick di sanguinamento la riavviano."
L["A bar left out is not touched by an import."] = "Una barra esclusa non viene toccata da un'importazione."
L["A bar per group member with their level and how far through it they are. Every member running Naowh Forever shares their experience, even with this off; anyone else shows their level. Updates wait until combat ends. Move it in the HUD Editor."] = "Una barra per ogni membro del gruppo con il suo livello e quanto è avanti in esso. Ogni membro che usa Naowh Forever condivide la sua esperienza, anche con questa opzione disattivata; gli altri mostrano il livello. Gli aggiornamenti attendono la fine del combattimento. Spostala nell'Editor HUD."
L["A bar with the name, a turn arrow and the distance, while a waypoint is set."] = "Una barra con il nome, una freccia di direzione e la distanza, mentre è impostato un punto di riferimento."
L["A batch of ten, four done, as it shows while you craft."] = "Un lotto di dieci, quattro fatti, come appare mentre crei."
L["A black outline round the clock."] = "Un contorno nero attorno all'orologio."
L["A black outline round the FPS / MS readout and the counts, in place of the soft shadow."] = "Un contorno nero attorno a FPS / MS e ai conteggi, al posto dell'ombra morbida."
L["A black outline round the text, in place of the soft shadow."] = "Un contorno nero attorno al testo, al posto dell'ombra morbida."
L["A button per set: click to equip, Shift-click to save what you wear into it, Ctrl-click to rename it, right-click to change its icon, and + to save a new one. The set you wear is outlined. Move it in the HUD Editor."] = "Un pulsante per set: clicca per equipaggiarlo, Maiusc-clic per salvarvi ciò che indossi, Ctrl-clic per rinominarlo, clic destro per cambiarne l'icona, e + per salvarne uno nuovo. Il set che indossi è evidenziato. Spostalo nell'Editor HUD."
L["A button that flags or unflags you for PvP, showing which you are."] = "Un pulsante che attiva o disattiva il tuo stato PvP, mostrando quale hai."
L["A campfire in range and Camp Benefits about to run out."] = "Un fuoco da campo in portata e Camp Benefits sul punto di scadere."
L["A campfire in range and no Camp Benefits."] = "Un fuoco da campo in portata e nessun Camp Benefits."
L["A campfire is in range"] = "Un fuoco da campo è in portata"
L["A card behind the text, a soft dark fade, or nothing at all."] = "Una scheda dietro il testo, una sfumatura scura leggera o niente."
L["A card over the pin with what it is and how far."] = "Una scheda sul segnalino con cosa è e quanto dista."
L["A cast part way through, swept around the ring."] = "Un lancio a metà, che scorre attorno all'anello."
L["A cast someone interrupted, held for the fade time."] = "Un lancio interrotto da qualcuno, mantenuto per il tempo di dissolvenza."
L["A cast while your interrupt is on cooldown, with the tick where it comes back."] = "Un lancio mentre la tua interruzione è in recupero, con la tacca di quando torna."
L["A cast while your interrupt is ready."] = "Un lancio mentre la tua interruzione è pronta."
L["A cast you cannot interrupt, with its shield."] = "Un lancio che non puoi interrompere, con il suo scudo."
L["A character shows up here after you log into it with Instance Tracker on. Track Alts shows the others: rested experience and durability, from the last time that character was logged in."] = "Un personaggio appare qui dopo che vi hai effettuato l'accesso con il Tracciamento istanze attivo. Traccia alt mostra gli altri: esperienza da riposo e durabilità, dall'ultima volta che quel personaggio ha effettuato l'accesso."
L["A choice among its rewards: pick this one."] = "Una scelta tra le sue ricompense: scegli questa."
L["A command name can only use letters, numbers and underscores."] = "Il nome di un comando può contenere solo lettere, numeri e trattini bassi."
L["A consumable or personal buff with less time than this left counts as missing."] = "Un consumabile o beneficio personale con meno tempo rimasto di questo conta come mancante."
L["A crosshair at the middle of your screen."] = "Un mirino al centro dello schermo."
L["A cup beside a healer who is drinking."] = "Una tazza accanto a un guaritore che sta bevendo."
L["A custom command can't reload. Type /reload."] = "Un comando personalizzato non può ricaricare. Digita /reload."
L["A dark or light fill and edge behind each line, or none."] = "Un riempimento e bordo scuro o chiaro dietro ogni riga, o nessuno."
L["A dark panel behind the icons."] = "Un pannello scuro dietro le icone."
L["A door on each dungeon and raid entrance on the world map, for the sides the Journal lists. Hover it for the levels, click it for a waypoint."] = "Una porta su ogni ingresso di spedizione e incursione sulla mappa del mondo, per le fazioni elencate dal Diario. Passa sopra per i livelli, clicca per un punto di riferimento."
L["A dot on a slot where a better enchant for your level waits: hover it for the advice, click it to ask in Trade."] = "Un punto su uno spazio dove ti attende un incantamento migliore per il tuo livello: passa sopra per il consiglio, clicca per chiedere nel canale Commercio."
L["A fading trail behind the cursor."] = "Una scia che sbiadisce dietro il cursore."
L["A few quick steps for %s only, its own modules included."] = "Alcuni rapidi passi solo per %s, compresi i suoi moduli."
L["A game that opens when a flight starts and closes when you land."] = "Un gioco che si apre quando inizia un volo e si chiude quando atterri."
L["A gear set called %s already exists."] = "Esiste già un set di equipaggiamento chiamato %s."
L["A glow on the moving edge of the fill."] = "Un bagliore sul bordo mobile del riempimento."
L["A hidden quest chain across Azeroth: click each thing in the world in turn. It gives a lot of experience, and ends in the Cozy Sleeping Bag; rest in it for a bonus to experience."] = "Una catena di missioni nascosta per tutta Azeroth: clicca ogni cosa nel mondo a turno. Dà molta esperienza e termina con il Cozy Sleeping Bag; riposa in esso per un bonus all'esperienza."
L["A key that opens Group Inspect."] = "Un tasto che apre Ispezione gruppo."
L["A key that shows a boss's loot at your cursor."] = "Un tasto che mostra il bottino di un boss al cursore."
L["A key that uses this item."] = "Un tasto che usa questo oggetto."
L["A later point needs it. "] = "Un punto successivo lo richiede. "
L["A later step."] = "Un passo successivo."
L["A line for each quest you turn in, with the experience and money it gave. Reward items show as their own lines."] = "Una riga per ogni missione consegnata, con l'esperienza e il denaro ottenuti. Gli oggetti ricompensa appaiono come righe a sé."
L["A line for every reputation gain, from quests and kills alike."] = "Una riga per ogni guadagno di reputazione, sia da missioni che da uccisioni."
L["A line for the experience from each kill. Quest experience is on the quest's own line."] = "Una riga per l'esperienza di ogni uccisione. L'esperienza delle missioni è sulla riga della missione."
L["A line from the pin down to a map pin's or corpse's spot."] = "Una linea dal segnalino giù fino al punto di un segnalino della mappa o di un cadavere."
L["A line in chat with the item's link."] = "Una riga in chat con il link dell'oggetto."
L["A line in their color on their player tooltip."] = "Una riga nel loro colore nel tooltip del giocatore."
L["A line to share them with."] = "Una riga con cui condividerli."
L["A line under the ID saying which keys copy it (Ctrl-Shift-C: copy ID or Wowhead link). Off, the shortcut still works; the line is just not shown."] = "Una riga sotto l'ID che dice quali tasti lo copiano (Ctrl-Maiusc-C: copia ID o link Wowhead). Se disattivata, la scorciatoia funziona comunque; la riga semplicemente non appare."
L["A look you do not have yet|r"] = "Un aspetto che non hai ancora|r"
L["a macro made on this character"] = "una macro creata su questo personaggio"
L["A macro this character does not have yet: the import makes it."] = "Una macro che questo personaggio non ha ancora: l'importazione la crea."
L["A minimap button that opens %s. /nf%s does the same, and the Top Bar can carry it too. Saved for this computer."] = "Un pulsante della minimappa che apre %s. /nf%s fa lo stesso, e anche la Barra superiore può contenerlo. Salvato per questo computer."
L["A Naowh weights line, or a WoWSims EP export (in WoWSims: Stat Weights, Copy to Current EP, Export)"] = "Una riga di pesi Naowh, o un'esportazione EP di WoWSims (in WoWSims: Stat Weights, Copy to Current EP, Export)"
L["A Naowh weights line, or a WoWSims EP export."] = "Una riga di pesi Naowh, o un'esportazione EP di WoWSims."
L["A new session, before any experience."] = "Una nuova sessione, prima di qualsiasi esperienza."
L["A parry by your target took 40% off its swing."] = "Una parata del tuo bersaglio ha tolto il 40% al suo colpo."
L["A party of five, a card each."] = "Un gruppo di cinque, una scheda ciascuno."
L["A player's score on their tooltip. One running Naowh Forever shares theirs; anyone else's is read from their gear when you hover them, within inspect range and out of combat."] = "Il punteggio di un giocatore nel suo tooltip. Chi usa Naowh Forever condivide il proprio; quello degli altri viene letto dal loro equipaggiamento quando ci passi sopra, entro la portata di ispezione e fuori dal combattimento."
L["A profile"] = "Un profilo"
L["a quest"] = "una missione"
L["A quest reward for the other faction; try the Auction House."] = "Una ricompensa di missione per l'altra fazione; prova la Casa d'aste."
L["A raid for %d players"] = "Un'incursione per %d giocatori"
L["A raid, a row each."] = "Un'incursione, una riga ciascuno."
L["A rare someone else is fighting."] = "Un raro che qualcun altro sta combattendo."
L["A rare you have killed before."] = "Un raro che hai già ucciso."
L["A rare you have not killed yet."] = "Un raro che non hai ancora ucciso."
L["A reward from the quest "] = "Una ricompensa della missione "
L["A ring around your cursor so you never lose it in a busy fight, with your global cooldown and casts swept around it."] = "Un anello attorno al cursore così non lo perdi mai in uno scontro concitato, con il tempo di recupero globale e i lanci che vi scorrono attorno."
L["A round in progress."] = "Un turno in corso."
L["A row of icons for missing food, flask, elixir and scroll buffs, your own class buff, and class buffs missing in your group. Out of combat only: the game keeps your buffs from addons in combat, so the icons keep what they showed. Hover one to pick a carried item to use. Move them in the HUD Editor."] = "Una fila di icone per i benefici mancanti di cibo, tonico, elisir e pergamena, il tuo beneficio di classe e i benefici di classe mancanti nel gruppo. Solo fuori dal combattimento: in combattimento il gioco nasconde i tuoi benefici agli addon, quindi le icone mantengono ciò che mostravano. Passa sopra una per scegliere un oggetto da usare. Spostale nell'Editor HUD."
L["A running gold per hour beside the newest line, counting money and item value since your first loot this session."] = "Un oro all'ora aggiornato accanto all'ultima riga, che conta denaro e valore degli oggetti dal tuo primo bottino di questa sessione."
L["A Scan Prices button on the auction house. It reads every listing and keeps the lowest buyout for each item, for this realm and faction. Blizzard allows one full scan every 15 minutes."] = "Un pulsante Scansiona prezzi nella casa d'aste. Legge ogni inserzione e tiene il prezzo d'acquisto immediato più basso per ogni oggetto, per questo reame e fazione. Blizzard consente una scansione completa ogni 15 minuti."
L["A junk icon on the bag slot of each item marked as junk."] = "Un'icona di cianfrusaglia sullo spazio della borsa di ogni oggetto segnato come cianfrusaglia."
L["A second panel for your focus, to keep Sap or Polymorph's time on one enemy while you fight another."] = "Un secondo pannello per il tuo focus, per tenere d'occhio il tempo di Tramortimento o Metamorfosi su un nemico mentre ne combatti un altro."
L["A set that goes on by itself while you ride or rest, and the set you had on goes back afterwards."] = "Un set che si equipaggia da solo mentre cavalchi o riposi, e il set che avevi torna dopo."
L["A shooting game for flights: click the other faction's races as fast as you can."] = "Un gioco di tiro per i voli: clicca le razze dell'altra fazione il più velocemente possibile."
L["A short flash of text entering and leaving combat. Move it in the HUD Editor."] = "Un breve lampo di testo all'entrata e all'uscita dal combattimento. Spostalo nell'Editor HUD."
L["A small bar with your next trainer visit and your gold, to leave up while you level. Move it by dragging."] = "Una piccola barra con la tua prossima visita all'istruttore e il tuo oro, da tenere visibile mentre sali di livello. Spostala trascinandola."
L["A small health bar for the other tank in your group, shown while you are tanking: tank role, Bear Form, Defensive Stance or Righteous Fury. The other tank is whoever has the tank role or the raid's Main Tank assignment. Click it to target them. Changes made in combat apply when the fight ends. Move it in the HUD Editor."] = "Una piccola barra della salute per l'altro difensore del gruppo, visibile mentre fai da difensore: ruolo di difensore, Forma d'Orso, Postura Difensiva o Furia del Giusto. L'altro difensore è chi ha il ruolo di difensore o l'assegnazione di difensore principale dell'incursione. Cliccala per selezionarlo. Le modifiche fatte in combattimento si applicano alla fine dello scontro. Spostala nell'Editor HUD."
L["A soft glow around Naowh's arrow."] = "Un bagliore morbido attorno alla freccia di Naowh."
L["A soft glow beside each icon."] = "Un bagliore morbido accanto a ogni icona."
L["A soft glow round it in your accent color."] = "Un bagliore morbido attorno nel tuo colore di accento."
L["A soft glow round it in your rank's color."] = "Un bagliore morbido attorno nel colore del tuo grado."
L["A soft ring pulses around each target."] = "Un anello morbido pulsa attorno a ogni bersaglio."
L["a sound to refresh"] = "un suono per rinnovare"
L["A sound, or the Speech text read aloud, as each cast starts."] = "Un suono, o il testo vocale letto ad alta voce, all'inizio di ogni lancio."
L["A sound, or the Speech text read aloud. Text to Speech can stutter on some PCs, as the game waits while Windows speaks it; a Sound costs nothing."] = "Un suono, o il testo vocale letto ad alta voce. La sintesi vocale può scattare su alcuni PC, perché il gioco aspetta mentre Windows parla; un suono non costa nulla."
L["A spell an import could not place because you do not know it yet goes into its saved slot when you learn it, unless you have put something else there."] = "Un incantesimo che un'importazione non ha potuto posizionare perché non lo conosci ancora va nel suo spazio salvato quando lo apprendi, a meno che tu non ci abbia messo qualcos'altro."
L["A Stack button on the card when part-filled stacks of an item can be combined."] = "Un pulsante Impila sulla scheda quando pile parziali di un oggetto si possono unire."
L["A star on the world map for every rare you have not killed, where it is most likely to be. Hover one for the rare and its drops, its other spawn spots and, if it patrols, its way; click it for a waypoint, right-click it to keep its spots and way shown."] = "Una stella sulla mappa del mondo per ogni raro che non hai ucciso, dove è più probabile trovarlo. Passa sopra per il raro e i suoi bottini, gli altri punti di comparsa e, se pattuglia, il suo percorso; clicca per un punto di riferimento, clic destro per tenere visibili punti e percorso."
L["A string to share it with."] = "Una stringa con cui condividerlo."
L["A supporter"] = "Un sostenitore"
L["A team member"] = "Un membro del team"
L["A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there."] = "Un testo sulla barra: cliccalo nell'anteprima per cambiarlo. Ogni testo appare in un solo punto della barra: sceglierne uno mostrato altrove lo sposta lì."
L["A tick on the bar where your interrupt comes off cooldown. Hidden while it is ready."] = "Una tacca sulla barra dove la tua interruzione torna disponibile. Nascosta quando è pronta."
L["A title bar naming the mob the threat is on."] = "Una barra del titolo con il nome del mostro su cui c'è la minaccia."
L["A trained spell drops into its saved slot."] = "Un incantesimo appreso va nel suo spazio salvato."
L["a vendor sells the formula"] = "un mercante vende la formula"
L["A warning when a rare is near"] = "Un avviso quando un raro è vicino"
L["A warning when a rare is near you: when its nameplate comes up, you mouse over it or target it. A card with its portrait: right-click it to close it, and its pin sets a waypoint to the rare. Move it in the HUD Editor."] = "Un avviso quando un raro è vicino a te: quando compare la sua barra del nome, ci passi sopra o lo selezioni. Una scheda con il suo ritratto: clic destro per chiuderla, e il suo segnalino imposta un punto di riferimento verso il raro. Spostala nell'Editor HUD."
L["A warning while a hunter or warlock has no pet out. A warlock who sacrificed their demon is left alone. Move it in the HUD Editor."] = "Un avviso mentre un cacciatore o uno stregone non ha il famiglio fuori. Uno stregone che ha sacrificato il suo demone viene lasciato stare. Spostalo nell'Editor HUD."
L["A word of your own on the icon."] = "Una parola tua sull'icona."
L["A world drop from %d kinds of mob"] = "Un bottino mondiale da %d tipi di mostro"
L["A WoW quiz for campfires and flights, or any time with /naowh quiz."] = "Un quiz su WoW per fuochi da campo e voli, o in qualsiasi momento con /naowh quiz."
L["A yellow ! on the world map at every quest giver with a quest you can pick up that still gives experience. Hover it for the quests; click it for a waypoint."] = "Un ! giallo sulla mappa del mondo su ogni assegnatore di missioni con una missione che puoi prendere e che dà ancora esperienza. Passa sopra per le missioni; clicca per un punto di riferimento."
L["A zone older than this is no longer shown, since the player has likely moved on."] = "Una zona più vecchia di questo non viene più mostrata, dato che il giocatore si è probabilmente spostato."
L["Abandon %s?"] = "Abbandonare %s?"
L["Abilities"] = "Abilità"
L["about "] = "circa "
L["about %d:%02d"] = "circa %d:%02d"
L["About %s at your last scan%s%s"] = "Circa %s alla tua ultima scansione%s%s"
L["About %s spent"] = "Circa %s spesi"
L["About a minute."] = "Circa un minuto."
L["Above"] = "Sopra"
L["Acc."] = "Prec."
L["Accent: missing the class blessing. Lighter: running out. Deeper: only players with their own."] = "Accento: manca la benedizione di classe. Più chiaro: sta finendo. Più scuro: solo giocatori con la propria."
L["Accept Quests"] = "Accetta missioni"
L["Accept Shared Dungeon Quests"] = "Accetta missioni di spedizione condivise"
L["Accepts a quest as soon as its text opens. Use the Modifier to read it first."] = "Accetta una missione appena si apre il suo testo. Usa il modificatore per leggerla prima."
L["Accepts dungeon quests your group shares with you straight away."] = "Accetta subito le missioni di spedizione che il gruppo condivide con te."
L["Accepts shared quests"] = "Accetta le missioni condivise"
L["Accepts the popup on screen: a summons, a resurrection, a group invite."] = "Accetta il popup sullo schermo: un'evocazione, una resurrezione, un invito in gruppo."
L["Accepts, hands in and shares quests for you, and remembers the reward you saved for a quest. The Modifier skips them or triggers them, as Modifier Does says."] = "Accetta, consegna e condivide le missioni per te, e ricorda la ricompensa salvata per una missione. Il modificatore le salta o le attiva, come indicato in Effetto del modificatore."
L["Account"] = "Account"
L["Account "] = "Account "
L["Account macros"] = "Macro dell'account"
L["Account this hour: %d of %d"] = "Account in quest'ora: %d su %d"
L["Accuracy"] = "Precisione"
L["Action Bars is switched off."] = "Barre delle azioni è disattivato."
L["Action Bars' own window, with your class's saved sets."] = "La finestra di Barre delle azioni, con i set salvati della tua classe."
L["Active"] = "Attivo"
L["Activity Bar"] = "Barra delle attività"
L["Activity Bar Color"] = "Colore barra delle attività"
L["Activity Bar Height"] = "Altezza barra delle attività"
L["Add %d item to your junk list: %s%s?"] = "Aggiungere %d oggetto alla tua lista cianfrusaglie: %s%s?"
L["Add %d items to your junk list: %s%s?"] = "Aggiungere %d oggetti alla tua lista cianfrusaglie: %s%s?"
L["Add %d macro as character macros?%s"] = "Aggiungere %d macro come macro del personaggio?%s"
L["Add %d macros as character macros?%s"] = "Aggiungere %d macro come macro del personaggio?%s"
L["Add %s"] = "Aggiungi %s"
L["Add %s (%d items) as a new BiS list?"] = "Aggiungere %s (%d oggetti) come nuova lista BiS?"
L["Add %s to the Consumable Bar?"] = "Aggiungere %s alla Barra dei consumabili?"
L["Add a backup pick"] = "Aggiungi una scelta di riserva"
L["Add a Button"] = "Aggiungi un pulsante"
L["Add a stat"] = "Aggiungi una statistica"
L["Add an item ID, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "Aggiungi l'ID di un oggetto o importa una lista. Il cibo conta qualsiasi beneficio Ben nutrito, gli altri oggetti il proprio beneficio; aggiungi gli ID degli incantesimi di beneficio solo per un oggetto che ne dà un altro. Nulla viene aggiunto automaticamente. Passa sopra un promemoria per scegliere un oggetto configurato dalle borse. I promemoria si fermano in combattimento; i menu degli oggetti funzionano fuori dal combattimento. Quando e dove appaiono si imposta in AuraBuffs > Impostazioni."
L["Add consumables, put them in order, and set each one up."] = "Aggiungi consumabili, mettili in ordine e configura ciascuno."
L["Add Items"] = "Aggiungi oggetti"
L["Add Latency"] = "Aggiungi latenza"
L["Add macros someone shared with you."] = "Aggiungi macro che qualcuno ha condiviso con te."
L["Add or remove your commands, turn each one on or off, or restore the defaults."] = "Aggiungi o rimuovi i tuoi comandi, attiva o disattiva ciascuno, o ripristina i predefiniti."
L["Add Slash Command"] = "Aggiungi comando slash"
L["Add the %s build %s (%d points)?"] = "Aggiungere la build %s %s (%d punti)?"
L["Add Themes to RestedXP"] = "Aggiungi temi a RestedXP"
L["Add to BiS List"] = "Aggiungi alla lista BiS"
L["Add to Shopping List"] = "Aggiungi alla lista della spesa"
L["Add to the Left Side"] = "Aggiungi al lato sinistro"
L["Add to the Right Side"] = "Aggiungi al lato destro"
L["Add your consumables, put them in order, set each one up."] = "Aggiungi i tuoi consumabili, mettili in ordine, configura ciascuno."
L["Add your own lines to the bag macros. They are kept after the item, whatever is in your bags."] = "Aggiungi righe tue alle macro delle borse. Vengono tenute dopo l'oggetto, qualunque cosa ci sia nelle borse."
L["Added %d consumable to the Consumable Bar."] = "Aggiunto %d consumabile alla Barra dei consumabili."
L["Added %d consumables to the Consumable Bar."] = "Aggiunti %d consumabili alla Barra dei consumabili."
L["Added %d consumables; %d were already listed or past the %d limit."] = "Aggiunti %d consumabili; %d erano già in lista o oltre il limite di %d."
L["Added %d of %d: %s."] = "Aggiunti %d su %d: %s."
L["Added %d."] = "Aggiunti %d."
L["Added %s to this character. Drag it to a bar from the game's macro window (/macro)."] = "%s aggiunta a questo personaggio. Trascinala su una barra dalla finestra delle macro del gioco (/macro)."
L["Added %s to your BiS %s as #%d."] = "%s aggiunto al tuo BiS %s come n. %d."
L["Added %s to your BiS %s."] = "%s aggiunto al tuo BiS %s."
L["Added next to your Library, never over it"] = "Aggiunte accanto alla tua libreria, mai al suo posto"
L["Added next to your own lists, never over them"] = "Aggiunte accanto alle tue liste, mai al loro posto"
L["Added next to your saved builds"] = "Aggiunte accanto alle tue build salvate"
L["Adding Items"] = "Aggiunta oggetti"
L["Addon Font"] = "Carattere dell'addon"
L["Addon List"] = "Lista addon"
L["Addon Memory"] = "Memoria addon"
L["Adds \"- [1] + Add to List\" under a recipe's reagents: the materials Buy on AH would buy for that many crafts go on a shopping list, from anywhere. At the auction house the list shows beside it: Check Prices looks each one up and warns in red when one is well above your last scan, then Buy All goes through the list one material at a time, each bought only when you confirm its final price. A material you can make for less from its parts, such as a bar from ore, has its parts bought instead."] = "Aggiunge \"- [1] + Aggiungi alla lista\" sotto i reagenti di una ricetta: i materiali che Compra in CdA comprerebbe per quel numero di creazioni vanno in una lista della spesa, da ovunque. Alla casa d'aste la lista appare accanto: Controlla prezzi li cerca uno per uno e avvisa in rosso quando uno è molto sopra la tua ultima scansione, poi Compra tutto scorre la lista un materiale alla volta, comprando ciascuno solo quando confermi il prezzo finale. Un materiale che puoi creare spendendo meno dai suoi componenti, come una barra dal minerale, fa comprare invece i componenti."
L["Adds a Bags column to the chosen recipe's reagents, showing how many of each you carry."] = "Aggiunge una colonna Borse ai reagenti della ricetta scelta, che mostra quanti ne porti di ciascuno."
L["Adds a Bank column to the chosen recipe's reagents, showing how many of each are in your bank."] = "Aggiunge una colonna Banca ai reagenti della ricetta scelta, che mostra quanti ne hai in banca di ciascuno."
L["Adds a button to the popup that swaps every lower rank on your bars for the highest rank you know. Keyboard and controller bars land in the same slot. Right-click a spell in the popup to keep its lower ranks, for downranking. Rank swaps only happen out of combat."] = "Aggiunge al popup un pulsante che sostituisce ogni grado inferiore sulle barre con il grado più alto che conosci. Le barre per tastiera e controller finiscono nello stesso spazio. Clic destro su un incantesimo nel popup per tenerne i gradi inferiori, per il downranking. Le sostituzioni di grado avvengono solo fuori dal combattimento."
L["Adds a Land button to come down at the next stop on the way."] = "Aggiunge un pulsante Atterra per scendere alla prossima tappa del percorso."
L["Adds a line that flags any slot whose enchant is missing or differs from the ones you captured with Capture Current Enchants. Hover it for the details."] = "Aggiunge una riga che segnala ogni spazio il cui incantamento manca o è diverso da quelli catturati con Cattura incantamenti attuali. Passa sopra per i dettagli."
L["Adds a mana spell's healing or damage per mana and per second to its tooltip."] = "Aggiunge al tooltip di un incantesimo che usa mana la cura o il danno per mana e al secondo."
L["Adds a second, orange number next to each recipe: how many you could make after buying the reagents vendors sell, such as Weak Flux or Coarse Thread. The recipe's reagents then say how many of each to buy."] = "Aggiunge un secondo numero arancione accanto a ogni ricetta: quante potresti crearne dopo aver comprato i reagenti venduti dai mercanti, come Fondente debole o Filo grezzo. I reagenti della ricetta indicano allora quanti comprarne di ciascuno."
L["Adds how long the visit lasted."] = "Aggiunge quanto è durata la visita."
L["Adds target and focus switching to the meter's title bar."] = "Aggiunge alla barra del titolo dell'indicatore il cambio tra bersaglio e focus."
L["Adds the average experience here."] = "Aggiunge l'esperienza media qui."
L["Adds the coins looted."] = "Aggiunge le monete raccolte."
L["Adds the consumables in your bags that are not on the bar yet."] = "Aggiunge i consumabili nelle borse che non sono ancora sulla barra."
L["Adds the deaths."] = "Aggiunge le morti."
L["Adds the experience gained."] = "Aggiunge l'esperienza ottenuta."
L["Adds the materials for one more craft."] = "Aggiunge i materiali per una creazione in più."
L["Adds the Naowh themes to RestedXP's theme list."] = "Aggiunge i temi di Naowh alla lista dei temi di RestedXP."
L["Adds the reputation gained."] = "Aggiunge la reputazione ottenuta."
L["Adds the visits at this level."] = "Aggiunge le visite a questo livello."
L["Adds the visits until you level."] = "Aggiunge le visite fino al prossimo livello."
L["Adds your bonus healing or spell damage; off shows the spell's base numbers."] = "Aggiunge la tua cura bonus o il danno magico; se disattivato mostra i valori base dell'incantesimo."
