L["after the 5% cut"] = "dopo la commissione del 5%"
L["After visiting a trainer, a small window lists the abilities you just learned. Abilities from a tome or a quest show a moment after you learn them. Drag one from the window onto your bars."] = "Dopo aver visitato un istruttore, una piccola finestra elenca le abilità appena apprese. Le abilità da un tomo o da una missione appaiono un attimo dopo averle apprese. Trascinane una dalla finestra alle tue barre."
