L["At a profession trainer who teaches any of your favourite recipes that you can learn now (star one before its name, or right-click it in the list), a window beside the trainer's lists them with their cost: Learn one, or Learn All."] = "Da un istruttore di professione che insegna una delle tue ricette preferite che puoi apprendere ora (metti una stella prima del nome, o clic destro nella lista), una finestra accanto all'istruttore le elenca con il loro costo: Apprendine una, o Apprendi tutto."
L["At a vendor who sells them, tops your class reagents and ammo up to what you carry, and prints what it spent. Off by default: it spends gold for you."] = "Da un mercante che li vende, rifornisce i reagenti di classe e le munizioni fino alla quantità da portare, e stampa quanto ha speso. Disattivato in modo predefinito: spende oro al posto tuo."
L["At level %d"] = "Al livello %d"
L["At login, names any of your characters with mail that expires within three days. It knows each character's mail from the last time it opened a mailbox."] = "All'accesso, indica i tuoi personaggi con posta che scade entro tre giorni. Conosce la posta di ogni personaggio dall'ultima volta che ha aperto una cassetta postale."
L["At the auction house, a window beside it lists the patterns, plans and manuals of your favourite recipes that you have not learned or bought, with what they cost now. Buy finds the cheapest and asks before Accept buys it."] = "Alla casa d'aste, una finestra accanto elenca schemi, progetti e manuali delle tue ricette preferite che non hai appreso o comprato, con il loro costo attuale. Compra trova il più economico e chiede conferma prima che Accetta lo compri."
