L["Buys from this merchant, in one click, every checked reagent it sells, for that many crafts, whatever is already in your bags. Set the number with the - and + beside it; uncheck a reagent to leave it out."] = "Compra da questo mercante, con un clic, ogni reagente spuntato che vende, per quel numero di creazioni, indipendentemente da ciò che hai già nelle borse. Imposta il numero con - e + accanto; togli la spunta a un reagente per escluderlo."
