L["Drag the corner to resize. Wheel: row height (Shift: spacing, Ctrl: text). Right-click a row for what it shows. Click the name or status line to change them."] = "Trascina l'angolo per ridimensionare. Rotellina: altezza righe (Maiusc: spaziatura, Ctrl: testo). Clic destro su una riga per cosa mostra. Clicca il nome o la riga di stato per cambiarli."
L["Drag the icon to a bar"] = "Trascina l'icona su una barra"
L["Drag the right edge"] = "Trascina il bordo destro"
L["Drag the right edge for width, a line's bottom for height. Wheel: text size (Shift: spacing, Ctrl: lines). Right-click a line for what it shows."] = "Trascina il bordo destro per la larghezza, il fondo di una riga per l'altezza. Rotellina: dimensione testo (Maiusc: spaziatura, Ctrl: righe). Clic destro su una riga per cosa mostra."
L["Drag the right edge for width. Wheel: text size (Shift: height). Click a bonus or the time to show or hide it. Right-click for more."] = "Trascina il bordo destro per la larghezza. Rotellina: dimensione testo (Maiusc: altezza). Clicca un bonus o il tempo per mostrarlo o nasconderlo. Clic destro per altro."
L["Drag to make the map bigger or smaller.\nRight-click: back to 100%."] = "Trascina per ingrandire o rimpicciolire la mappa.\nClic destro: torna al 100%."
L["Drag to move it, right-click to take it off."] = "Trascina per spostarlo, clic destro per toglierlo."
L["Drag to move, x to remove, + to add."] = "Trascina per spostare, x per rimuovere, + per aggiungere."
L["Drag to move. Click x to remove."] = "Trascina per spostare. Clicca x per rimuovere."
L["Drag to place it."] = "Trascina per posizionarlo."
