L["Each camp feature's own icon before its bonus."] = "L'icona di ogni struttura dell'accampamento prima del suo bonus."
L["Each class's name or icon, under its button or beside it when the bar is vertical."] = "Il nome o l'icona di ogni classe, sotto il suo pulsante o accanto quando la barra è verticale."
L["Each dungeon or raid visit while Instance Tracker is on: how long you were inside, the coins you looted and the experience you gained. Reputation gained is listed under the visit. Coming back to the same group within the hour, before you reset it, continues that visit, and the time outside is not counted. Other characters stay saved, and show here when Track Alts is on. Repairs and vendor sales are not counted. Older visits drop off the end of the list."] = "Ogni visita a una spedizione o incursione con Tracciamento istanze attivo: quanto tempo sei rimasto dentro, le monete raccolte e l'esperienza ottenuta. La reputazione ottenuta è elencata sotto la visita. Tornare allo stesso gruppo entro l'ora, prima di azzerarla, continua quella visita, e il tempo passato fuori non viene contato. Gli altri personaggi restano salvati e appaiono qui quando Traccia alt è attivo. Riparazioni e vendite ai mercanti non vengono contate. Le visite più vecchie escono dalla fine della lista."
L["Each line fades out after %ss."] = "Ogni riga sbiadisce dopo %ss."
L["Each one is an account macro. Put it on a bar once and it keeps itself current: loot a better potion, conjure fresh food or pick up bandages and the macro is rewritten to use the best you carry.\n\nThe game does not let macros change mid-fight, so a change during combat waits until it ends."] = "Ognuna è una macro dell'account. Mettila su una barra una volta e si aggiorna da sola: raccogli una pozione migliore, evoca cibo fresco o raccogli bende e la macro viene riscritta per usare il meglio che porti.\n\nIl gioco non permette di cambiare le macro durante uno scontro, quindi una modifica in combattimento aspetta che finisca."
L["Each point of the trail in a color of its own."] = "Ogni punto della scia con un colore proprio."
L["Each slot's item level, in its icon's corner."] = "Il livello oggetto di ogni spazio, nell'angolo della sua icona."
L["Each visit, with its time, coins, and experience."] = "Ogni visita, con tempo, monete ed esperienza."
L["Earned in"] = "Ottenuto in"
