L["How big the tracker is."] = "Quanto è grande il tracciamento."
L["How close a book has to be before it pings."] = "Quanto deve essere vicino un libro prima che segnali."
L["How early you can press your next spell before the current one finishes, in milliseconds. 100 to 400 suits most: lower is more responsive, higher is more forgiving of latency. Melee around your ping + 100, ranged around your ping + 150."] = "Quanto prima puoi premere il prossimo incantesimo prima che finisca quello attuale, in millisecondi. Da 100 a 400 va bene per quasi tutti: più basso è più reattivo, più alto tollera meglio la latenza. Corpo a corpo circa il tuo ping + 100, distanza circa il tuo ping + 150."
L["How far along an icon starts to fade, from 0% (at once) to 95% (at the very end)."] = "A che punto un'icona inizia a sbiadire, da 0% (subito) a 95% (proprio alla fine)."
L["How far below your level gear has to be for Old Common Gear."] = "Quanto sotto il tuo livello deve essere l'equipaggiamento per Vecchio equipaggiamento comune."
L["How Group Inspect shows a party and a raid, with sample players."] = "Come Ispezione gruppo mostra un gruppo e un'incursione, con giocatori di esempio."
L["How little Camp Benefits time counts as needing a refresh."] = "Quanto poco tempo di Camp Benefits conta come da rinnovare."
L["How long an interrupted cast stays up. 0 hides it at once."] = "Quanto resta visibile un lancio interrotto. 0 lo nasconde subito."
L["How long before the effect runs out it shows again."] = "Quanto tempo prima che l'effetto scada riappare."
L["How long each line stays before it fades."] = "Quanto resta ogni riga prima di sbiadire."
L["How long it takes to get there at your speed."] = "Quanto ci vuole per arrivarci alla tua velocità."
L["How long the current fight has run, on screen while you fight. Move it in the HUD Editor."] = "Quanto dura lo scontro in corso, sullo schermo mentre combatti. Spostalo nell'Editor HUD."
L["How long the fight lasted, in chat when it ends."] = "Quanto è durato lo scontro, in chat quando finisce."
L["How long the next level takes at your current rate."] = "Quanto richiede il prossimo livello al tuo ritmo attuale."
L["How long this session has run."] = "Da quanto dura questa sessione."
L["How many crafts Add to List adds the materials for."] = "Per quante creazioni Aggiungi alla lista aggiunge i materiali."
