L["How many crafts to ask for."] = "Quante creazioni chiedere."
L["How many decimals the per mana numbers show."] = "Quanti decimali mostrano i valori per mana."
L["How many icons fit in a row before the next row starts."] = "Quante icone stanno in una riga prima di iniziarne un'altra."
L["How many new instances this account has entered this hour."] = "Quante nuove istanze ha aperto questo account in quest'ora."
L["How many of this material you hand the crafter. Ticking the box fills in all the crafts need; - and + change it by one."] = "Quanti di questo materiale consegni all'artigiano. Spuntare la casella inserisce tutti quelli richiesti dalle creazioni; - e + lo cambiano di uno."
