L["Invites the crafter to your group, with a whisper saying it is for crafts from their profession. Once they are in your party, Ask sends the order in party chat instead of whispering it. Greyed out once they are in your group, or while you are in a group and not its leader or an assistant."] = "Invita l'artigiano nel tuo gruppo, con un sussurro che spiega che è per creazioni della sua professione. Una volta nel gruppo, Chiedi invia l'ordine nella chat di gruppo invece di sussurrarlo. In grigio quando è già nel gruppo, o mentre sei in un gruppo senza esserne il capo o un assistente."
L["Invites your target. Works in combat."] = "Invita il tuo bersaglio. Funziona in combattimento."
