L["Makes the set's macros that this character does not have. A macro you already have, by name and text or by text alone, is used as it is: never copied twice or changed."] = "Crea le macro del set che questo personaggio non ha. Una macro che hai già, per nome e testo o solo per testo, viene usata così com'è: mai copiata due volte né modificata."
L["Makes this recipe a favourite, or no longer one. Favourites get a star in the list, and the Filter menu's Favorites shows only them. Right-click a recipe in the list does the same."] = "Rende questa ricetta preferita, o la toglie dai preferiti. Le preferite hanno una stella nella lista, e Preferiti nel menu Filtro mostra solo quelle. Clic destro su una ricetta nella lista fa lo stesso."
L["Makes this recipe a favourite, or no longer one. With Train Favorites on, a trainer who teaches it offers it when you visit; with Search Favorites AH on, its pattern, plans or manual is listed at the auction house to search for."] = "Rende questa ricetta preferita, o la toglie dai preferiti. Con Apprendi preferite attivo, un istruttore che la insegna te la propone quando lo visiti; con Cerca preferite in CdA attivo, il suo schema, progetto o manuale viene elencato alla casa d'aste da cercare."
