L["Opens another player's profession link in this window, to order crafts from them. Choose a recipe, set how many crafts, tick the materials you bring (or type how many), and Add to Order. The order on the right has a suggested tip per craft that you can change; Ask sends the crafter one message per craft with the amount, your materials and the tip: in party chat when they are in your party, else as a whisper. Prices and the tip need an auction house scan."] = "Apre in questa finestra il link della professione di un altro giocatore, per ordinargli creazioni. Scegli una ricetta, imposta quante creazioni, spunta i materiali che porti (o scrivi quanti) e Aggiungi all'ordine. L'ordine a destra ha una mancia suggerita per creazione che puoi cambiare; Chiedi invia all'artigiano un messaggio per creazione con quantità, materiali e mancia: nella chat di gruppo se è nel tuo gruppo, altrimenti come sussurro. Prezzi e mancia richiedono una scansione della casa d'aste."
L["Opens its settings and leaves the HUD Editor."] = "Apre le sue impostazioni ed esce dall'Editor HUD."
L["Opens the Aim Trainer now, out of combat."] = "Apre ora l'Allenamento di mira, fuori dal combattimento."
L["Opens the AuraBuffs window, where you add each item by its item ID and buff spell ID."] = "Apre la finestra di AuraBuffs, dove aggiungi ogni oggetto con il suo ID oggetto e l'ID dell'incantesimo di beneficio."
L["Opens the Consumable Bar's settings."] = "Apre le impostazioni della Barra dei consumabili."
L["Opens the copy card on a sample spell. Select the ID or link, then Ctrl+C."] = "Apre la scheda di copia su un incantesimo di esempio. Seleziona l'ID o il link, poi Ctrl+C."
L["Opens the Dungeon Journal's Quest Tracker settings."] = "Apre le impostazioni del Tracciamento missioni del Diario delle spedizioni."
L["Opens the HUD Editor: click another Naowh Forever element for the bar to move with."] = "Apre l'Editor HUD: clicca un altro elemento di Naowh Forever con cui far muovere la barra."
L["Opens the Library Books tracker's settings."] = "Apre le impostazioni del tracciamento dei Libri della biblioteca."
L["Opens the planner on its Builds tab."] = "Apre il pianificatore sulla scheda Build."
L["Opens the quest tracker out in the world, on the dungeon your quests are for."] = "Apre il tracciamento missioni nel mondo, sulla spedizione a cui si riferiscono le tue missioni."
L["Opens the quest tracker when you enter a dungeon with quests for you."] = "Apre il tracciamento missioni quando entri in una spedizione con missioni per te."
L["Opens the quiz now, or closes it."] = "Apre ora il quiz, o lo chiude."
L["Opens the Run Timer settings."] = "Apre le impostazioni del Timer della run."
L["Opens the Sleeping Bag tracker's settings."] = "Apre le impostazioni del tracciamento del Sacco a pelo."
L["Opens the Stat Weights window: each stat's worth to your spec, and your best upgrades by them."] = "Apre la finestra Pesi statistiche: il valore di ogni statistica per la tua specializzazione, e i tuoi migliori miglioramenti in base a essi."
L["Opens the window now, out of combat."] = "Apre ora la finestra, fuori dal combattimento."
