L["Plays as your target leaves melee range."] = "Suona quando il bersaglio esce dalla portata da corpo a corpo."
L["Plays Drop Alert with your list's first BiS, as you set it: up for a roll, dropped, then yours."] = "Riproduce Avviso bottino con il primo BiS della tua lista, come l'hai impostato: in palio, rilasciato, poi tuo."
L["Plays once each time your health drops below the threshold. If the game hides your health from addons mid-fight, it only plays out of combat."] = "Suona una volta ogni volta che la tua salute scende sotto la soglia. Se il gioco nasconde la tua salute agli addon durante lo scontro, suona solo fuori dal combattimento."
L["Plays once when your threat climbs past the threshold, and again only after it drops back below."] = "Suona una volta quando la tua minaccia supera la soglia, e di nuovo solo dopo che è tornata sotto."
L["Plays the map ping and names the book in chat when you come within range of one you still need. Once per book, until you walk away and come back."] = "Riproduce il ping della mappa e nomina il libro in chat quando arrivi in portata di uno che ti serve ancora. Una volta per libro, finché non ti allontani e torni."
L["Plays the map ping when a book is near."] = "Riproduce il ping della mappa quando un libro è vicino."
L["Plays the sound again this often while out of range. 0 plays it once."] = "Ripete il suono con questa frequenza mentre è fuori portata. 0 lo riproduce una volta."
L["Plays the sound picked here."] = "Riproduce il suono scelto qui."
L["Plays when it is time to refresh the camp."] = "Suona quando è ora di rinnovare l'accampamento."
L["Plays when the warning comes up, and flashes the game's icon on your taskbar."] = "Suona quando appare l'avviso, e fa lampeggiare l'icona del gioco nella barra delle applicazioni."
