L["Pops up when you enter a zone with books you still need, with a waypoint for each and your progress toward the next reward, and stays while you are in that zone. The X closes it until you enter another. Move it in the HUD Editor."] = "Appare quando entri in una zona con libri che ti servono ancora, con un punto di riferimento per ciascuno e i tuoi progressi verso la prossima ricompensa, e resta finché sei in quella zona. La X lo chiude finché non entri in un'altra. Spostalo nell'Editor HUD."
