L["Put back every setting this page has changed?"] = "Ripristinare ogni impostazione modificata da questa pagina?"
L["put down what you are holding first."] = "posa prima ciò che hai in mano."
L["Put every %s weight back to the defaults?"] = "Riportare ogni peso di %s ai valori predefiniti?"
L["Put every setting back to how it was before the onboarding?"] = "Riportare ogni impostazione a com'era prima della configurazione iniziale?"
L["Put every setting in this profile back to its default."] = "Riporta ogni impostazione di questo profilo al suo valore predefinito."
L["Put on in cities and inns, and taken off again when you leave."] = "Equipaggiato nelle città e nelle locande, e tolto quando esci."
L["Put on while you ride, and the set you had on goes back when you dismount."] = "Equipaggiato mentre cavalchi, e il set che avevi torna quando scendi dalla cavalcatura."
L["Put the XP Bar colors back to their defaults?"] = "Riportare i colori della barra PE ai valori predefiniti?"
L["Put the XP Bar's size and texts back to their defaults?"] = "Riportare dimensione e testi della barra PE ai valori predefiniti?"
L["Put this bar back in"] = "Reinserisci questa barra"
L["Puts a raid marker on your focus. Pressing the macro again on the same focus clears the marker."] = "Mette un indicatore d'incursione sul tuo focus. Premere di nuovo la macro sullo stesso focus rimuove l'indicatore."
L["Puts back every setting this page has changed, to the value you had before."] = "Ripristina ogni impostazione modificata da questa pagina al valore che avevi prima."
L["Puts back everything changed since the HUD Editor opened."] = "Ripristina tutto ciò che è cambiato dall'apertura dell'Editor HUD."
L["Puts back the last change. Ctrl + Z."] = "Annulla l'ultima modifica. Ctrl + Z."
L["Puts both back where the game shows them."] = "Rimette entrambi dove li mostra il gioco."
L["Puts every weight of this spec back to the defaults. Asks first."] = "Riporta ogni peso di questa specializzazione ai valori predefiniti. Chiede prima."
L["Puts food, drink and potions 10 or more levels below you, marked with a clock, first."] = "Mette per primi cibo, bevande e pozioni di 10 o più livelli sotto di te, segnati con un orologio."
L["Puts the bar back on the screen."] = "Rimette la barra sullo schermo."
L["Puts the bar's buttons back as they came: the Dungeon Journal and Discovery on the left, the BiS List and Training Planner on the right."] = "Rimette i pulsanti della barra come in origine: Diario delle spedizioni e Scoperte a sinistra, lista BiS e Pianificatore addestramento a destra."
L["Puts the card back above the middle of the screen, where it starts."] = "Rimette la scheda sopra il centro dello schermo, dove inizia."
L["Puts the cheapest item at the far end of the row instead of next to its anchor."] = "Mette l'oggetto più economico all'estremità opposta della riga invece che accanto all'ancoraggio."
L["Puts the cheapest item on your cursor, to drop or sell."] = "Mette l'oggetto più economico sul cursore, da gettare o vendere."
L["Puts the count just past the icon's edge."] = "Mette il conteggio appena oltre il bordo dell'icona."
L["Puts the key just past the icon's edge."] = "Mette il tasto appena oltre il bordo dell'icona."
L["Puts the materials for that many crafts on your shopping list: every checked reagent that vendors do not sell, whatever is in your bags. Uncheck a reagent to leave it out. At the auction house the list shows beside it, to check the prices and buy it all."] = "Mette nella lista della spesa i materiali per quel numero di creazioni: ogni reagente spuntato che i mercanti non vendono, indipendentemente da ciò che hai nelle borse. Togli la spunta a un reagente per escluderlo. Alla casa d'aste la lista appare accanto, per controllare i prezzi e comprare tutto."
L["Puts the popup back where it first showed."] = "Rimette il popup dove è apparso la prima volta."
