L["Puts the text just past the icon's edge."] = "Mette il testo appena oltre il bordo dell'icona."
L["Puts this recipe on the order on the right, with the number of crafts and the materials you bring. Changes made here after adding it change the order too. Up to %d recipes per order."] = "Mette questa ricetta nell'ordine a destra, con il numero di creazioni e i materiali che porti. Le modifiche fatte qui dopo averla aggiunta cambiano anche l'ordine. Fino a %d ricette per ordine."
L["Puts this set on. In combat, it goes on when the fight ends."] = "Equipaggia questo set. In combattimento, si equipaggia alla fine dello scontro."
L["Puts your settings to one of Naowh's setups, or walks you through them again."] = "Imposta le tue impostazioni su una delle configurazioni di Naowh, o te le ripropone passo per passo."
