L["Shown with threat"] = "Visibile con minaccia"
L["Shown: click to hide it."] = "Visibile: clicca per nasconderlo."
L["Shows a dungeon's bosses and loot beside the world map while you are inside."] = "Mostra i boss e il bottino di una spedizione accanto alla mappa del mondo mentre sei dentro."
L["Shows a healing item's icon the moment your health drops below the threshold, in combat too: the game shows and hides it itself. Move it in the HUD Editor."] = "Mostra l'icona di un oggetto curativo nel momento in cui la tua salute scende sotto la soglia, anche in combattimento: è il gioco stesso a mostrarla e nasconderla. Spostala nell'Editor HUD."
L["Shows a sample spell's tooltip with the line as your settings draw it."] = "Mostra il tooltip di un incantesimo di esempio con la riga come la disegnano le tue impostazioni."
L["Shows a zone's level range when you hover it on the world map."] = "Mostra l'intervallo di livelli di una zona quando ci passi sopra sulla mappa del mondo."
L["Shows an icon on screen while you know Find Herbs, Find Minerals or Find Fish but are tracking none of them. Click it to start tracking: left-click for the first, right-click for the second, middle-click for the third. Hover it to see which is which. Hidden in combat. Move it in the HUD Editor."] = "Mostra un'icona sullo schermo mentre conosci Ricerca Erbe, Ricerca Minerali o Find Fish ma non ne stai tracciando nessuno. Cliccala per iniziare a tracciare: clic sinistro per il primo, clic destro per il secondo, clic centrale per il terzo. Passaci sopra per vedere quale è quale. Nascosta in combattimento. Spostala nell'Editor HUD."
L["Shows each Sleeping Bag step, with how to reach the next one and a waypoint."] = "Mostra ogni passo del Sacco a pelo, con come raggiungere il successivo e un punto di riferimento."
L["Shows every bonus again; click one on the preview to hide it."] = "Mostra di nuovo ogni bonus; clicca uno nell'anteprima per nasconderlo."
L["Shows how many of each you carry."] = "Mostra quanti ne porti di ciascuno."
L["Shows if you're ahead of or behind your other characters, and colors past levels by it."] = "Mostra se sei avanti o indietro rispetto agli altri personaggi, e colora i livelli passati di conseguenza."
L["Shows it again a little before its effect runs out."] = "Lo mostra di nuovo poco prima che il suo effetto scada."
L["Shows only part of the raid."] = "Mostra solo parte dell'incursione."
L["Shows or hides the list of every element."] = "Mostra o nasconde la lista di tutti gli elementi."
L["Shows the factions earned where you are beside the world map."] = "Mostra accanto alla mappa del mondo le fazioni ottenibili dove ti trovi."
L["Shows the key that uses each button."] = "Mostra il tasto che usa ogni pulsante."
L["Shows the meter with sample bars where it sits on your screen, for ten seconds. Out of combat only."] = "Mostra l'indicatore con barre di esempio dove si trova sullo schermo, per dieci secondi. Solo fuori dal combattimento."
L["Shows the other tank's debuffs beside their health bar, in combat too: tank-buster stacks, boss debuffs and anything you can dispel."] = "Mostra le penalità dell'altro difensore accanto alla sua barra della salute, anche in combattimento: cumuli contro i difensori, penalità dei boss e tutto ciò che puoi dissolvere."
L["Shows the parts of the world map you have not explored yet, darkened."] = "Mostra, oscurate, le parti della mappa del mondo che non hai ancora esplorato."
L["Shows the row only once your bags are this full. 0 shows it all the time."] = "Mostra la riga solo quando le borse sono così piene. 0 la mostra sempre."
L["Shows the Sleeping Bag steps still to do on your map; click one for a waypoint."] = "Mostra sulla mappa i passi del Sacco a pelo ancora da fare; clicca uno per un punto di riferimento."
L["Shows the warning with its sound, about your target if you can attack it."] = "Mostra l'avviso con il suo suono, riguardo al tuo bersaglio se puoi attaccarlo."
L["Shows this bonus on the bar: %s."] = "Mostra questo bonus sulla barra: %s."
L["Shows this recipe's reagents in your objective tracker, with how many you have of each."] = "Mostra i reagenti di questa ricetta nel tracciamento obiettivi, con quanti ne hai di ciascuno."
L["Shows this visit's time, coins, and experience."] = "Mostra tempo, monete ed esperienza di questa visita."
L["Shows up once you take the talent"] = "Appare dopo aver preso il talento"
L["Shows who Naowh, the developers, the moderators and our Legendary and Epic patrons are: a badge by their name in chat, a line on their tooltip and, if you want it, a banner when one of them joins your group."] = "Mostra chi sono Naowh, gli sviluppatori, i moderatori e i nostri sostenitori leggendari ed epici: un distintivo accanto al nome in chat, una riga nel loro tooltip e, se vuoi, un banner quando uno di loro entra nel tuo gruppo."
L["Shows your BiS stars to players who inspect you with Naowh Forever."] = "Mostra le stelle BiS ai giocatori che ti ispezionano con Naowh Forever."
L["Shows your note and tag on a player's tooltip."] = "Mostra la tua nota e la tua etichetta nel tooltip di un giocatore."
L["Shows your other characters' visits."] = "Mostra le visite degli altri personaggi."
