L["Takes everything the moment you loot, with Blizzard's loot window kept out of sight, so the feed is all you see. Works with or without the game's auto loot. Hold Shift while looting to get the window back. It also appears whenever something cannot be taken: a group roll, a locked item, or bags too full."] = "Raccoglie tutto nel momento in cui saccheggi, tenendo nascosta la finestra del bottino di Blizzard, così vedi solo il flusso. Funziona con o senza la raccolta automatica del gioco. Tieni premuto Maiusc mentre raccogli per riavere la finestra. Appare anche quando qualcosa non si può prendere: un tiro di gruppo, un oggetto bloccato o borse troppo piene."
