L["The AuraBuffs window: the consumables to watch."] = "La finestra di AuraBuffs: i consumabili da monitorare."
L["The bar and the FPS / MS readout fade to Faded Opacity until you hover them. Their buttons still click while faded."] = "La barra e FPS / MS sbiadiscono fino a Opacità sbiadita finché non ci passi sopra. I loro pulsanti si cliccano anche da sbiaditi."
L["The bar as it shows outside a fight."] = "La barra come appare fuori dagli scontri."
L["The bar as it sits on your screen."] = "La barra come appare sullo schermo."
L["The best scores of the players you have met, in this mode."] = "I record dei giocatori che hai incontrato, in questa modalità."
L["The BiS List's own window, and its Stat Weights window."] = "La finestra della lista BiS, e la sua finestra Pesi statistiche."
L["The BiS rankings behind the BiS List."] = "Le classifiche BiS dietro la lista BiS."
L["The book count is what players report; not confirmed yet."] = "Il numero di libri è quello riportato dai giocatori; non ancora confermato."
L["The boss or place it comes from."] = "Il boss o il luogo da cui proviene."
L["The buffs show while you hover the icon."] = "I benefici appaiono mentre passi sopra l'icona."
L["The build's next talent cannot be taken now: your talents are not the build's."] = "Il prossimo talento della build non si può prendere ora: i tuoi talenti non sono quelli della build."
L["The calendar cannot be opened from the Top Bar with a gamepad."] = "Il calendario non si può aprire dalla Barra superiore con un gamepad."
L["The card at the end of a round."] = "La scheda alla fine di un turno."
L["The cheapest items in your bags as a row of icons, cheapest first. Ctrl-click an icon to delete it, or click it to sell it while a vendor is open. Middle-click to ignore an item. Move it in the HUD Editor."] = "Gli oggetti più economici nelle borse come fila di icone, dal più economico. Ctrl-clic su un'icona per eliminarlo, o clicca per venderlo mentre un mercante è aperto. Clic centrale per ignorare un oggetto. Spostala nell'Editor HUD."
L["The class's name, or its class icon, which fits however small the buttons are."] = "Il nome della classe, o la sua icona, che ci sta per quanto piccoli siano i pulsanti."
L["The color of the line on the tooltip."] = "Il colore della riga nel tooltip."
L["The Consumable Bar will ask about those items again."] = "La Barra dei consumabili chiederà di nuovo per quegli oggetti."
L["The consumables your reminders watch"] = "I consumabili monitorati dai tuoi promemoria"
L["The consumables your reminders watch."] = "I consumabili monitorati dai tuoi promemoria."
L["The Cozy Sleeping Bag's hidden quest chain, step by step."] = "La catena di missioni nascosta del Cozy Sleeping Bag, passo per passo."
L["The crowd control on your target; pick which in the Crowd Control card below."] = "Gli effetti di controllo sul tuo bersaglio; scegli quali nella scheda Controllo qui sotto."
L["The Ctrl-click line, and Click to sell while a vendor is open."] = "La riga del Ctrl-clic, e Clicca per vendere mentre un mercante è aperto."
L["The cursor left still."] = "Il cursore lasciato fermo."
L["The debuffs on your target you pick in the Debuffs card below, like Mortal Strike."] = "Le penalità sul tuo bersaglio che scegli nella scheda Penalità qui sotto, come Colpo Mortale."
L["The default is %s."] = "Il predefinito è %s."
L["The default is %s. Click to put it back."] = "Il predefinito è %s. Clicca per ripristinarlo."
L["The Disenchant window cannot open in combat."] = "La finestra di disincanto non si può aprire in combattimento."
L["The Dungeon Quest Tracker's window."] = "La finestra del Tracciamento missioni di spedizione."
L["The dungeons on whose ground the list shows. Contested ones and the raids are always listed. Also the switch beside the Journal's search."] = "Le spedizioni sul cui territorio appare la lista. Quelle contese e le incursioni sono sempre elencate. È anche l'interruttore accanto alla ricerca del Diario."
L["The Edit Items window."] = "La finestra Modifica oggetti."
L["The extra gap between your aura and Righteous Fury and the class buttons."] = "Lo spazio extra tra la tua aura e Furia del Giusto e i pulsanti delle classi."
L["The fastest way to any waypoint."] = "La via più veloce verso qualsiasi punto di riferimento."
L["The first %d of %d; type more to narrow it down."] = "I primi %d su %d; scrivi di più per restringere."
L["The first time someone speaks, ask their Naowh Forever for their zone with a hidden addon whisper. Players without it never see the question."] = "La prima volta che qualcuno parla, chiedi al suo Naowh Forever la sua zona con un sussurro nascosto dell'addon. I giocatori senza non vedono mai la domanda."
L["The flight time to each destination when you hover it on the flight master's map."] = "Il tempo di volo verso ogni destinazione quando ci passi sopra sulla mappa del maestro di volo."
L["The font for damage and healing numbers, over enemies and over your character. Off leaves the game's own font alone."] = "Il carattere per i numeri di danni e cure, sopra i nemici e sopra il tuo personaggio. Disattivato lascia il carattere del gioco."
L["The font for the rest of the game: menus, chat, tooltips and names. Off leaves the game's own fonts alone."] = "Il carattere per il resto del gioco: menu, chat, tooltip e nomi. Disattivato lascia i caratteri del gioco."
L["The font for this addon's windows and HUD. Font settings on a feature use it unless they pick their own. Saved for this computer.|n|nTakes effect after a /reload."] = "Il carattere per le finestre e l'HUD di questo addon. Le impostazioni dei caratteri di una funzione lo usano a meno che non ne scelgano uno proprio. Salvato per questo computer.|n|nHa effetto dopo un /reload."
L["The FPS / MS readout and the online counts on the buttons."] = "FPS / MS e i conteggi online sui pulsanti."
L["The FPS / MS readout stays up."] = "FPS / MS resta visibile."
L["The game does not name this fight yet: its kills count once the raid opens."] = "Il gioco non nomina ancora questo scontro: le sue uccisioni contano quando l'incursione apre."
L["The game has no PvP rank for you yet. It shows once the season has started."] = "Il gioco non ha ancora un grado PvP per te. Appare quando la stagione è iniziata."
L["The game has no route for %s, and its quest giver's spot is not known."] = "Il gioco non ha un percorso per %s, e la posizione del suo assegnatore non è nota."
L["The game is not passing addon messages right now (in an encounter): ask again after it."] = "Il gioco non sta inoltrando i messaggi degli addon in questo momento (in uno scontro): chiedi di nuovo dopo."
L["The game lists no rank rewards for this season yet."] = "Il gioco non elenca ancora ricompense di grado per questa stagione."
L["The game would not disenchant this (skill too low?). Skipped until you reload."] = "Il gioco non ha voluto disincantarlo (abilità troppo bassa?). Saltato fino al prossimo reload."
L["The game's own alert sounds first, then the addon's. Each plays as you pick it."] = "Prima i suoni di avviso del gioco, poi quelli dell'addon. Ognuno viene riprodotto quando lo scegli."
L["The gap between the two."] = "Lo spazio tra i due."
L["The gap between two buttons."] = "Lo spazio tra due pulsanti."
L["The Gear Sets window, with every set and what you can do with it."] = "La finestra Set di equipaggiamento, con ogni set e cosa puoi farci."
L["The group can be disbanded once the fight is over."] = "Il gruppo si può sciogliere quando lo scontro è finito."
L["The group's paladins and the blessing each gives every class."] = "I paladini del gruppo e la benedizione che ciascuno dà a ogni classe."
L["The guild name under a player's name."] = "Il nome della gilda sotto il nome di un giocatore."
L["The highest rank this season"] = "Il grado più alto di questa stagione"
L["The icon grows and shrinks with it."] = "L'icona cresce e si rimpicciolisce con esso."
L["The inspect window in the BiS List's look, with their score, gear check, talents and history."] = "La finestra di ispezione nello stile della lista BiS, con punteggio, controllo dell'equipaggiamento, talenti e cronologia."
L["The item's cooldown sweeps over its icon."] = "Il tempo di recupero dell'oggetto scorre sulla sua icona."
L["The item's quality"] = "La qualità dell'oggetto"
L["The item, your star and what happened, on screen for a while."] = "L'oggetto, la tua stella e cosa è successo, sullo schermo per un po'."
L["The items the Buffs & Consumables reminders watch."] = "Gli oggetti monitorati dai promemoria di Benefici e consumabili."
L["The Journal beside the world map: bosses and loot in dungeons, factions outside."] = "Il Diario accanto alla mappa del mondo: boss e bottino nelle spedizioni, fazioni all'esterno."
L["The Journal's own window."] = "La finestra del Diario."
L["The key that changes Accept Quests, Hand In Quests, Pick Quests From NPCs and sharing."] = "Il tasto che modifica Accetta missioni, Consegna missioni, Scegli le missioni dai PNG e la condivisione."
L["The key that changes Auto Gossip for that NPC."] = "Il tasto che modifica Auto Gossip per quel PNG."
L["The key that opens the BiS List."] = "Il tasto che apre la lista BiS."
L["The key that opens the Journal."] = "Il tasto che apre il Diario."
L["The key that opens the Quest List window."] = "Il tasto che apre la finestra Lista missioni."
L["The last %ds, scrolling %s%s"] = "Gli ultimi %ds, scorrimento %s%s"
L["The last fight's time stays on screen until the next one starts."] = "Il tempo dell'ultimo scontro resta sullo schermo finché non inizia il successivo."
L["The last part of each melee swing, shaded."] = "L'ultima parte di ogni colpo in corpo a corpo, ombreggiata."
L["the last profile cannot be deleted"] = "l'ultimo profilo non può essere eliminato"
L["The last profile cannot be deleted."] = "L'ultimo profilo non può essere eliminato."
L["The latest %d kills. First counted: %s."] = "Le ultime %d uccisioni. Prima contata: %s."
L["The latest %d. First counted: %s."] = "Gli ultimi %d. Primo contato: %s."
L["The leader's zone on each Group Finder listing, and every member's zone when you hover it."] = "La zona del capo su ogni annuncio della Ricerca gruppo, e la zona di ogni membro quando ci passi sopra."
L["The level you are on as it runs, then completed levels, newest first."] = "Il livello in cui sei mentre procede, poi i livelli completati, dal più recente."
L["The line round the bar."] = "La linea attorno alla barra."
L["The list this character uses."] = "La lista usata da questo personaggio."
L["The longest a buff can last to show; longer ones like Arcane Intellect stay hidden."] = "La durata massima di un beneficio per essere mostrato; quelli più lunghi come Intelletto Arcano restano nascosti."
L["The macros the addon writes and keeps up to date for you, out of combat. Switch one on here, or take it to your bars from Smart Macros in Naowh's Forge."] = "Le macro che l'addon scrive e tiene aggiornate per te, fuori dal combattimento. Attivane una qui, o portala sulle barre da Macro intelligenti in Naowh's Forge."
L["The Man. The King."] = "L'uomo. Il re."
L["The map's window, the Journal beside the world map and Boss Loot at Cursor."] = "La finestra della mappa, il Diario accanto alla mappa del mondo e Bottino del boss al cursore."
L["The marks on the game's own character panel, as it looks (or EllesmereUI's), without the Naowh Character Panel. With it on, its slots have them already."] = "I segni sul pannello del personaggio del gioco, così com'è (o quello di EllesmereUI), senza il pannello del personaggio Naowh. Con quello attivo, i suoi spazi li hanno già."
L["The Middle-click line."] = "La riga del clic centrale."
L["The most recent completed levels."] = "I livelli completati più di recente."
L["the name is empty"] = "il nome è vuoto"
L["The name on it, and the community it is made for."] = "Il nome sopra, e la community per cui è fatto."
L["The Naowh Forever button on the minimap. The addon compartment entry and /naowh open this window either way."] = "Il pulsante di Naowh Forever sulla minimappa. La voce nel compartimento degli addon e /naowh aprono comunque questa finestra."
L["The Naowh Forever N next to the name of Naowh, the developers, the moderators and our Legendary and Epic patrons in chat."] = "La N di Naowh Forever accanto al nome di Naowh, degli sviluppatori, dei moderatori e dei nostri sostenitori leggendari ed epici in chat."
L["The newest line stays at the anchor; older lines stack in this direction."] = "La riga più recente resta all'ancoraggio; le più vecchie si impilano in questa direzione."
L["The next one frees in "] = "La prossima si libera tra "
L["the next rank of %s (cap %d)"] = "il prossimo grado di %s (massimo %d)"
L["The number on each icon counts your bank as well as your bags."] = "Il numero su ogni icona conta la banca oltre alle borse."
L["The order the points are taken in"] = "L'ordine in cui vengono presi i punti"
L["the pattern"] = "lo schema"
L["The people and projects behind Naowh Forever."] = "Le persone e i progetti dietro Naowh Forever."
L["The picked boss's loot and abilities, under the map."] = "Il bottino e le abilità del boss scelto, sotto la mappa."
L["The planner's own window, and a mini bar to leave up while you level."] = "La finestra del pianificatore, e una mini barra da tenere visibile mentre sali di livello."
L["The player list opens after combat."] = "La lista dei giocatori si apre dopo il combattimento."
L["The player's guild rank beside their guild name."] = "Il grado di gilda del giocatore accanto al nome della gilda."
L["The point of the bar that attaches."] = "Il punto della barra che si collega."
L["The point of the frame it attaches to."] = "Il punto del riquadro a cui si collega."
L["The purchase failed."] = "Acquisto non riuscito."
L["The purchase failed; the price may have changed."] = "Acquisto non riuscito; il prezzo potrebbe essere cambiato."
L["The purchase failed; the price may have changed.|r"] = "Acquisto non riuscito; il prezzo potrebbe essere cambiato.|r"
L["The quest tracker, and sharing dungeon quests with your group."] = "Il tracciamento missioni, e la condivisione delle missioni di spedizione con il gruppo."
L["The quests that reward a pick you do not have yet."] = "Le missioni che danno come ricompensa una scelta che non hai ancora."
L["The quiz opens when you sit down at a campfire and closes when you stand up."] = "Il quiz si apre quando ti siedi a un fuoco da campo e si chiude quando ti alzi."
L["The raid marker Mark Focus puts on your focus."] = "L'indicatore d'incursione che Segna focus mette sul tuo focus."
L["the rank before"] = "il grado precedente"
L["The ready ring shows with GCD Sweep on."] = "L'anello di pronto appare con Scorrimento GCD attivo."
L["The reagents your known spells use, such as Arcane Powder, candles, seeds, Symbols of Kings and Flash Powder, matched to the highest rank you know."] = "I reagenti usati dai tuoi incantesimi conosciuti, come Polvere arcana, candele, semi, Simboli dei Re e Polvere accecante, abbinati al grado più alto che conosci."
L["The red time left blinks, to catch your eye."] = "Il tempo rimasto in rosso lampeggia, per attirare l'attenzione."
L["The same required-level filter applies to every stack, not each item separately."] = "Lo stesso filtro del livello richiesto si applica a ogni pila, non a ogni oggetto separatamente."
L["The same sets as the character sheet's: equip, save, rename or delete them in the Gear Sets window."] = "Gli stessi set della scheda del personaggio: equipaggiali, salvali, rinominali o eliminali nella finestra Set di equipaggiamento."
L["The same with a Greater Blessing, for a class that shares one blessing, while you carry Symbols of Kings."] = "Lo stesso con una benedizione superiore, per una classe che condivide una benedizione, mentre porti Simboli dei Re."
L["The seconds left when the time turns red; it turns yellow at twice that."] = "I secondi rimasti quando il tempo diventa rosso; diventa giallo al doppio."
L["The serializer libraries are missing from this build."] = "Le librerie di serializzazione mancano da questa build."
L["The shape of Naowh's arrow."] = "La forma della freccia di Naowh."
L["The share of what the items sell for that the suggested tip adds on top of paying back the crafter's own materials. At least 1s unless set to 0."] = "La quota del prezzo di vendita degli oggetti che la mancia consigliata aggiunge oltre al rimborso dei materiali dell'artigiano. Almeno 1a, a meno che non sia impostata a 0."
L["The shortest time between two thanks to the same player."] = "Il tempo minimo tra due ringraziamenti allo stesso giocatore."
L["The Slot"] = "Lo spazio"
L["The slot it is for."] = "Lo spazio a cui è destinato."
L["The slots and stats only"] = "Solo gli spazi e le statistiche"
L["The space between Naowh's arrow and the text under it."] = "Lo spazio tra la freccia di Naowh e il testo sotto."
L["The spec your gear is weighed for. Automatic follows your talents: the tree with the most points (a druid's Feral is weighed for damage; pick Feral Tank for a bear)."] = "La specializzazione per cui viene pesato il tuo equipaggiamento. Automatico segue i tuoi talenti: l'albero con più punti (Ferino di un druido viene pesato per i danni; scegli Ferino difensore per un orso)."
L["The spot ahead of you, 312 yards away."] = "Il punto davanti a te, a 312 metri."
L["The spot off to your right."] = "Il punto alla tua destra."
L["The stat weights each spec starts with."] = "I pesi delle statistiche con cui parte ogni specializzazione."
L["The stealthed text while you are in stealth, as well as the reminder when you are not."] = "Il testo in furtività mentre sei in furtività, oltre al promemoria quando non lo sei."
L["The step and distance text under RestedXP's waypoint arrow."] = "Il testo di passo e distanza sotto la freccia di RestedXP."
L["The string is damaged: copy it again in full."] = "La stringa è danneggiata: copiala di nuovo per intero."
L["The suggested tip pays back the crafter's materials plus %d%% of what the items sell for (of all the materials, for a recipe that makes no item), rounded, at least 1s. Set a tip of your own in the order list on the right. Change the share in the Professions settings."] = "La mancia consigliata rimborsa i materiali dell'artigiano più il %d%% del prezzo di vendita degli oggetti (di tutti i materiali, per una ricetta che non crea un oggetto), arrotondata, almeno 1a. Imposta una mancia tua nella lista dell'ordine a destra. Cambia la quota nelle impostazioni di Professioni."
L["The swing timer needs WoW: Forever's own swing event."] = "Il timer dei colpi richiede l'evento di colpo di WoW: Forever."
L["The tag in the speaker's class color. Off, it is grey."] = "L'etichetta nel colore della classe di chi parla. Se disattivato, è grigia."
L["the talent above it"] = "il talento sopra"
L["The talent builds you saved in the Training Planner."] = "Le build di talenti salvate nel Pianificatore addestramento."
L["The Team"] = "Il team"
L["The text in the theme's accent color instead of gold."] = "Il testo nel colore di accento del tema invece che in oro."
L["The theme RestedXP uses: its own, or one of the Naowh themes."] = "Il tema usato da RestedXP: il suo, o uno dei temi di Naowh."
L["The time between the two sides. Click it for the calendar (not with a gamepad)."] = "L'ora tra i due lati. Cliccala per il calendario (non con un gamepad)."
L["The time left turns yellow, then red near the end, so you see crowd control about to break."] = "Il tempo rimasto diventa giallo, poi rosso verso la fine, così vedi quando un controllo sta per spezzarsi."
L["The time left, turning yellow, then red, as the camp runs down."] = "Il tempo rimasto, che diventa giallo, poi rosso, man mano che l'accampamento si esaurisce."
L["The tint on every button's icon: Naowh's own and any addon's."] = "La tinta sull'icona di ogni pulsante: quelli di Naowh e quelli di qualsiasi addon."
L["The Training Planner's help while you level: a toast when you level up with spells to train, and a panel beside your class trainer."] = "L'aiuto del Pianificatore addestramento mentre sali di livello: una notifica quando sali di livello con incantesimi da apprendere, e un pannello accanto all'istruttore di classe."
L["The unit frame the bar is attached to, or UIParent for the screen."] = "Il riquadro unità a cui è collegata la barra, o UIParent per lo schermo."
L["The weights"] = "I pesi"
L["The weights for %s."] = "I pesi per %s."
L["The window's border fades with it."] = "Il bordo della finestra sbiadisce con essa."
L["The word itself."] = "La parola stessa."
L["The XP of completed quests, and their text."] = "I PE delle missioni completate, e il loro testo."
L["The XP of quests still in progress, as a faded segment after the completed ones."] = "I PE delle missioni ancora in corso, come segmento sbiadito dopo quelle completate."
L["The XP of quests still in progress. By default the completed quests color, faded."] = "I PE delle missioni ancora in corso. In modo predefinito il colore delle missioni completate, sbiadito."
L["The zone of whoever speaks in a chat channel, guild chat or a whisper, in front of their message. The game never says where a stranger is, so a player is tagged once they are in the Group Finder, your guild, your friends or your group, came up in a /who, or answered from their own copy of Naowh Forever. Their first message may come through untagged."] = "La zona di chiunque parli in un canale di chat, nella chat di gilda o in un sussurro, davanti al messaggio. Il gioco non dice mai dove si trova uno sconosciuto, quindi un giocatore viene contrassegnato quando è nella Ricerca gruppo, nella tua gilda, tra i tuoi amici o nel tuo gruppo, è comparso in un /who, o ha risposto dalla propria copia di Naowh Forever. Il suo primo messaggio potrebbe arrivare senza contrassegno."
L["Their BiS"] = "Il loro BiS"
L["THEIR GEAR"] = "IL LORO EQUIPAGGIAMENTO"
L["Their gear, talents and history"] = "Il loro equipaggiamento, talenti e cronologia"
L["their materials + %d%%"] = "i loro materiali + %d%%"
L["Their materials:"] = "I loro materiali:"
L["Their Naowh Score at the top of the panel, with yours under it."] = "Il loro Naowh Score in cima al pannello, con il tuo sotto."
L["Their supporter badge in the window's corner, if they have one."] = "Il loro distintivo di sostenitore nell'angolo della finestra, se ne hanno uno."
L["Thelsamar"] = "Thelsamar"
L["Them"] = "Loro"
L["them all."] = "tutti."
