L["Theme presets for the addon's windows and HUD frames, plus a Custom option for your own colors. If text gets hard to read, pick Naowh (default). Saved for this computer.|n|nTakes effect after a /reload."] = "Temi preimpostati per le finestre e i riquadri HUD dell'addon, più un'opzione Personalizzato per i tuoi colori. Se il testo diventa difficile da leggere, scegli Naowh (predefinito). Salvato per questo computer.|n|nHa effetto dopo un /reload."
