L["Turn on the BiS List"] = "Attiva la lista BiS"
L["Turn on the BiS List and pick your BiS to see your best upgrades here."] = "Attiva la lista BiS e scegli il tuo BiS per vedere qui i tuoi migliori miglioramenti."
