L["Turn on the Campfire reminder to edit the bar here."] = "Attiva il promemoria del fuoco da campo per modificare qui la barra."
L["Turn on the Disenchant Window in the Professions settings first."] = "Attiva prima la Finestra disincanto nelle impostazioni di Professioni."
L["Turn on the Dungeon Journal"] = "Attiva il Diario delle spedizioni"
L["Turn on the Dungeon Journal for each dungeon's levels and quests here."] = "Attiva il Diario delle spedizioni per vedere qui i livelli e le missioni di ogni spedizione."
L["Turn on the Dungeon Journal to see the quests that reward your picks, with their chains and waypoints."] = "Attiva il Diario delle spedizioni per vedere le missioni che danno le tue scelte come ricompensa, con catene e punti di riferimento."
L["Turn on the Dungeon Journal to see what drops in dungeons for this slot."] = "Attiva il Diario delle spedizioni per vedere cosa si ottiene nelle spedizioni per questo spazio."
L["Turn on the Loot Feed to edit it here."] = "Attiva il Flusso bottino per modificarlo qui."
L["Turn on the Swing Timer"] = "Attiva il Timer colpi"
L["Turn on the Threat Meter"] = "Attiva l'Indicatore di minaccia"
