L["Turn on the Training Planner"] = "Attiva il Pianificatore addestramento"
L["Turn on XP per Hour to edit it here."] = "Attiva PE all'ora per modificarlo qui."
L["Turn this module on or off. Your settings are kept."] = "Attiva o disattiva questo modulo. Le tue impostazioni vengono tenute."
