L["Your buttons on either side of an optional clock, with FPS and latency underneath."] = "I tuoi pulsanti ai lati di un orologio facoltativo, con FPS e latenza sotto."
L["Your buttons on either side of an optional clock, with FPS and latency underneath. Arrange the buttons in the preview: drag one to move it, its x removes it, a side's + adds one. Move the bar in the HUD Editor."] = "I tuoi pulsanti ai lati di un orologio facoltativo, con FPS e latenza sotto. Disponi i pulsanti nell'anteprima: trascinane uno per spostarlo, la sua x lo rimuove, il + di un lato ne aggiunge uno. Sposta la barra nell'Editor HUD."
L["Your camp's bonuses and time left on screen, and a reminder when Camp Benefits runs out."] = "I bonus e il tempo rimasto del tuo accampamento sullo schermo, e un promemoria quando Camp Benefits scade."
L["Your camp's bonuses by the icon, always or while you hover it."] = "I bonus del tuo accampamento accanto all'icona, sempre o quando ci passi sopra."
L["Your cap is %d.\nFirst do the quest %s%s|r (%sskill %d):"] = "Il tuo massimo è %d.\nPrima fai la missione %s%s|r (%sabilità %d):"
