L["Your character panel (C) in the BiS List's look: each slot with its marks, your stats for your spec, and your Naowh Score under your level. The game keeps the panel and everything it does. With EllesmereUI, turning this on turns its character panel off, and off turns it back on, after a reload."] = "Il tuo pannello del personaggio (C) nello stile della lista BiS: ogni spazio con i suoi segni, le tue statistiche per la tua specializzazione e il tuo Naowh Score sotto il livello. Il gioco mantiene il pannello e tutto ciò che fa. Con EllesmereUI, attivare questa opzione disattiva il suo pannello del personaggio, e disattivarla lo riattiva, dopo un reload."
