L["Your equipment sets, the same ones the character sheet keeps."] = "I tuoi set di equipaggiamento, gli stessi della scheda del personaggio."
L["Your experience per hour on a small card, with time to level, played time, session length and recent level times. Hidden at max level. Hover it for Start, Pause and Reset (also /naowh xp start, pause or reset). Move it in the HUD Editor."] = "La tua esperienza all'ora su una piccola scheda, con tempo al livello, tempo di gioco, durata della sessione e tempi dei livelli recenti. Nascosta al livello massimo. Passaci sopra per Avvia, Pausa e Azzera (anche /naowh xp start, pause o reset). Spostala nell'Editor HUD."
L["Your experience. Its left end is a darker shade."] = "La tua esperienza. La sua estremità sinistra è di una tonalità più scura."
L["Your flight on a card: time left, the stops on a track, and the next stop."] = "Il tuo volo su una scheda: tempo rimasto, le tappe su un percorso e la prossima tappa."
L["Your focus target's casts on a bar of their own, colored by whether your interrupt is ready, with a tick where it comes off cooldown and a shield on casts you cannot interrupt. Your interrupt is the first you know of Pummel, Shield Bash, Kick, Counterspell, Earth Shock, Silence and Feral Charge. Move it in the HUD Editor."] = "I lanci del tuo focus su una barra propria, colorata in base a se la tua interruzione è pronta, con una tacca dove torna disponibile e uno scudo sui lanci che non puoi interrompere. La tua interruzione è la prima che conosci tra Pugno, Colpo di Scudo, Calcio, Controincantesimo, Scossa di Terra, Silenzio e Carica Ferina. Spostala nell'Editor HUD."
L["Your focus's name, tinted by class, with their class icon above the panel."] = "Il nome del tuo focus, colorato per classe, con la sua icona di classe sopra il pannello."
L["Your focus, set with NF Focus: their timers keep counting while you fight someone else."] = "Il tuo focus, impostato con NF Focus: i suoi timer continuano a contare mentre combatti qualcun altro."
L["Your game macros, not the Smart Macros, as one string to share."] = "Le tue macro di gioco, non le macro intelligenti, in un'unica stringa da condividere."
L["Your global cooldown swept around the ring, and a ready ring once it is over."] = "Il tuo tempo di recupero globale che scorre attorno all'anello, e un anello di pronto quando finisce."
L["YOUR GOLD"] = "IL TUO ORO"
L["Your group in range: who is missing a blessing, who is running out, and who only needs their own."] = "Il tuo gruppo in portata: a chi manca una benedizione, a chi sta finendo, e chi ha bisogno solo della propria."
L["Your group on a boss you are tanking."] = "Il tuo gruppo su un boss che stai difendendo."
