L["A ! in its own color for quest givers with a dungeon or raid quest."] = "Un ! con un colore proprio per gli assegnatori con una missione di spedizione o incursione."
L["A border round the active step."] = "Un bordo attorno al passo attivo."
L["A border round the whole window."] = "Un bordo attorno all'intera finestra."
L["A glow around each reminder icon, since each is a buff that is missing or running out."] = "Un bagliore attorno a ogni icona di promemoria, dato che ognuna è un beneficio mancante o in esaurimento."
