L["A glow around the reminder while you have no Camp Benefits."] = "Un bagliore attorno al promemoria mentre non hai Camp Benefits."
L["A minimap button that opens %s. Saved for this computer."] = "Un pulsante della minimappa che apre %s. Salvato per questo computer."
L["A panel behind the whole window."] = "Un pannello dietro l'intera finestra."
L["A progress bar of the guide, a line, or nothing."] = "Una barra di avanzamento della guida, una linea o niente."
L["A reminder when a weapon has no sharpening stone, weightstone or oil on it."] = "Un promemoria quando un'arma non ha pietra per affilare, pietra zavorra od olio applicati."
L["A row that is done and the steps after the active one."] = "Una riga completata e i passi dopo quello attivo."
L["A sample: the meter in the game shows your fights."] = "Un esempio: il misuratore nel gioco mostra i tuoi scontri."
L["A soft shine along the top of the bar and a glow where your XP ends."] = "Una luce morbida lungo la parte alta della barra e un bagliore dove finiscono i tuoi PE."
L["A text around the bar: click it on the preview to change it. Each text shows in one place around it: picking one shown elsewhere moves it there. Only Played Time and Session Time show at max level."] = "Un testo attorno alla barra: cliccalo nell'anteprima per cambiarlo. Ogni testo appare in un solo punto attorno: sceglierne uno mostrato altrove lo sposta qui. Al livello massimo appaiono solo Tempo di gioco e Tempo della sessione."
