L["Crafting several at once (Create All, or Create with a count) shows one bar for the whole batch, drawn like the Flight Timer: the recipe, how many are done and the time left on all of them. It sits where the Flight Timer is, as nobody crafts in flight: move it in the HUD Editor as the Flight Timer."] = "Creare più oggetti alla volta (Crea tutto, o Crea con un numero) mostra una sola barra per l'intero lotto, disegnata come il Timer di volo: la ricetta, quanti ne sono fatti e il tempo rimasto per tutti. Sta dove si trova il Timer di volo, dato che nessuno crea in volo: spostala nell'Editor HUD come Timer di volo."
