L["A .png, .tga or .blp file. Make its width and height powers of two, such as 128, 256, 512 or 1024, to be safe; a small one, 128 or 256, is good for a pattern that is repeated with Tile Image, and Tile Size says how wide each repeat is. A .jpg is most likely not read by the game: open it and save it as a .png first."] = "Un file .png, .tga o .blp. Per sicurezza, larghezza e altezza devono essere potenze di due, come 128, 256, 512 o 1024; uno piccolo, 128 o 256, va bene per un motivo ripetuto con Affianca immagine, e Dimensione riquadro indica quanto è larga ogni ripetizione. Un .jpg molto probabilmente non viene letto dal gioco: aprilo e salvalo prima come .png."
L["A button that invites everyone on your invite buttons."] = "Un pulsante che invita tutti quelli sui tuoi pulsanti di invito."
