L["In the game's Interface\\AddOns folder make a folder of your own, such as MyBackgrounds, and put the file in it, for instance MyBackgrounds\\panel.png. A folder of your own is not touched when add-ons are updated. Restart the game once so it finds the file."] = "Nella cartella Interface\\AddOns del gioco crea una tua cartella, come MyBackgrounds, e mettici il file, per esempio MyBackgrounds\\panel.png. Una tua cartella non viene toccata quando gli addon si aggiornano. Riavvia il gioco una volta perché trovi il file."
L["In the Window card, under Picture, pick Your Own Picture in Image, and write the path from Interface in Custom Image, with backslashes and with the file's extension: Interface\\AddOns\\MyBackgrounds\\panel.png. Pick None or another picture in Image to go back."] = "Nella scheda Finestra, sotto Immagine, scegli La tua immagine in Immagine di sfondo, e scrivi il percorso da Interface in Immagine personalizzata, con le barre rovesciate e l'estensione del file: Interface\\AddOns\\MyBackgrounds\\panel.png. Scegli Nessuna o un'altra immagine in Immagine di sfondo per tornare indietro."
