L["Unexplored Areas off"] = "Aree inesplorate disattivato"
L["Use Class Teleports"] = "Usa i teletrasporti di classe"
L["Use the Hearthstone"] = "Usa la Pietra del Ritorno"
L["wait %s"] = "attesa %s"
L["Waypoint Only Where Steps End"] = "Punto di riferimento solo a fine tappa"
L["What a journey may use besides walking, flights and ships."] = "Cosa può usare un viaggio oltre a piedi, voli e navi."
L["What each row has before its figures: icon, rank and name, each with its settings behind its cog."] = "Cosa ha ogni riga prima delle cifre: icona, posizione e nome, ognuno con le sue impostazioni dietro il suo ingranaggio."
L["What it shows in a row."] = "Cosa mostra in una riga."
L["What the fade does with the mouse."] = "Cosa fa la dissolvenza con il mouse."
L["What the line says, and its size, font and color."] = "Cosa dice la riga, e la sua dimensione, carattere e colore."
L["What the mouse does while the window is locked."] = "Cosa fa il mouse mentre la finestra è bloccata."
L["What the window lists, for which session, and when it shows."] = "Cosa elenca la finestra, per quale sessione e quando appare."
L["What to do in the settings"] = "Cosa fare nelle impostazioni"
L["What you are short on when you reach a city or inn."] = "Ciò che ti manca quando arrivi in una città o locanda."
L["When the meter shows: always, in combat, in a group or never."] = "Quando appare il misuratore: sempre, in combattimento, in gruppo o mai."
L["When the window shows: always, or only in a place or in combat."] = "Quando appare la finestra: sempre, o solo in un luogo o in combattimento."
L["When you are not among the rows shown, the last row is yours, with your rank."] = "Quando non sei tra le righe mostrate, l'ultima riga è la tua, con la tua posizione."
L["Where it goes"] = "Dove va"
L["Where the time sits, and its size, font and color."] = "Dove si trova il tempo, e la sua dimensione, carattere e colore."
L["Whether the biggest bar or the list's total is a full bar."] = "Se a barra piena corrisponde la barra più grande o il totale della lista."
L["Which column stands where, left to right, in each row: the name, the total, the per-second figure, the share, or another list's total for the same player. Another list's total fills in after the fight."] = "Quale colonna sta dove, da sinistra a destra, in ogni riga: il nome, il totale, la cifra al secondo, la quota, o il totale di un'altra lista per lo stesso giocatore. Il totale di un'altra lista si riempie dopo lo scontro."
L["Which columns a row has and where, and how numbers, shares and per-second figures are written."] = "Quali colonne ha una riga e dove, e come vengono scritti numeri, quote e cifre al secondo."
L["Window Background"] = "Sfondo finestra"
L["Window Border"] = "Bordo finestra"
L["Window Position"] = "Posizione finestra"
L["Window Width"] = "Larghezza finestra"
L["With Enchanting open, a Disenchant button at the top of the window opens a window of every item in your bags you can disenchant: green, blue and purple weapons and armor (or type /naowh disenchant). Right-click an item to keep that one copy, or Shift-right-click to keep every copy of it, on any character, until you right-click it again. Disenchant All disenchants the rest one by one, one item per click, as the game asks a click for every disenchant. An item the game will not take (skill too low) is skipped until you reload. Closes when combat starts."] = "Con Incantamento aperto, un pulsante Disincanta in cima alla finestra apre una finestra con ogni oggetto nelle borse che puoi disincantare: armi e armature verdi, blu e viola (o scrivi /naowh disenchant). Clic destro su un oggetto per tenere quella copia, o Maiusc-clic destro per tenerne ogni copia, su qualsiasi personaggio, finché non lo clicchi di nuovo con il destro. Disincanta tutto disincanta il resto uno alla volta, un oggetto per clic, perché il gioco chiede un clic per ogni disincanto. Un oggetto che il gioco non accetta (abilità troppo bassa) viene saltato fino al prossimo reload. Si chiude quando inizia il combattimento."
L["Writes the per-second figure with /s after it."] = "Scrive la cifra al secondo seguita da /s."
L["Writes the time as (0:05)."] = "Scrive il tempo come (0:05)."
L["Writes the total and the per-second figure as one text with a bar between: 117 | 23."] = "Scrive il totale e la cifra al secondo come un unico testo separato da una barra: 117 | 23."
L["Writing"] = "Scrittura"
