L["HOW TO PLAY\n\nSET UP A SESSION\nEnter the pool in gold-and-silver format: an integer followed by \"g\", then an integer followed by \"s\" (for example, 10g50s). One gold is 100 silver, so 10g50s is 1,050 silver. All roll limits use the pool's total silver value. Party and Raid chat are supported; choose the channel your group is using. Both pool components must be whole numbers.\n\nSelect New Game to announce the session. Players, including the host, join by saying the configured join word in the selected chat. They can leave the lobby by saying the leave word. The host can use Last Call to remind the group, then select Start Rolling once at least two players have joined.\n\nCLASSIC\nWhen the host selects Start Rolling, chat announces that everyone can roll and gives the roll limit. Every joined player rolls from 1 to the pool's total silver value using /roll. With a 10g50s pool, each player rolls from 1 to 1,050. Use Announce Rolls to remind players who still need to roll and show the roll range.\n\nWhen everyone has rolled, the player with the lowest roll pays the player with the highest roll the difference between those original rolls. The difference is silver and is announced in gold-and-silver format (for example, 50 silver is shown as 0g50s). If the highest or lowest roll is tied, only the players tied at that extreme reroll to decide that side's winner or loser. The original high and low rolls determine the amount, even if a tie-break roll changes the order. If every player rolls the same number, nobody pays and everyone rolls again.\n\nDEATHROLL\nAfter the host starts the game, two joined players are selected at random. Gamble announces the selected players, then announces which one was randomly chosen to roll first.\n\nThe first player rolls from 1 to the pool's total silver value. With a 10g50s pool, the first roll is from 1 to 1,050. The two selected players then alternate: after each roll, the next player rolls from 1 to the value just rolled. Use Announce Rolls to identify whose turn it is and the current roll range. The first player to roll 1 loses; the other player wins the pool, announced in gold-and-silver format.\n\nENDING A SESSION\nThe host can select Cancel Session at any time before the session completes. The cancellation is announced in chat and the session ends for everyone. Completed sessions cannot be cancelled.\n\nGamble only announces results; it does not transfer gold. Players settle any announced amount themselves."] = "COME SI GIOCA\n\nPREPARARE UNA SESSIONE\nInserisci il piatto nel formato oro e argento: un numero intero seguito da \"g\", poi un numero intero seguito da \"s\" (per esempio, 10g50s). Un oro vale 100 argento, quindi 10g50s sono 1.050 argento. Tutti i limiti dei tiri usano il valore totale in argento del piatto. Sono supportate le chat di gruppo e di incursione; scegli il canale che usa il tuo gruppo. Entrambe le parti del piatto devono essere numeri interi.\n\nSeleziona Nuova partita per annunciare la sessione. I giocatori, organizzatore compreso, si uniscono scrivendo la parola per unirsi configurata nella chat selezionata. Possono lasciare la sala d'attesa scrivendo la parola per uscire. L'organizzatore può usare Ultima chiamata per ricordarlo al gruppo, poi selezionare Inizia a tirare quando si sono uniti almeno due giocatori.\n\nCLASSICO\nQuando l'organizzatore seleziona Inizia a tirare, la chat annuncia che tutti possono tirare e indica il limite del tiro. Ogni giocatore unito tira da 1 al valore totale in argento del piatto usando /roll. Con un piatto di 10g50s, ogni giocatore tira da 1 a 1.050. Usa Annuncia i tiri per ricordarlo a chi deve ancora tirare e mostrare l'intervallo del tiro.\n\nQuando tutti hanno tirato, il giocatore con il tiro più basso paga al giocatore con il tiro più alto la differenza tra quei tiri originali. La differenza è in argento e viene annunciata nel formato oro e argento (per esempio, 50 argento appare come 0g50s). Se il tiro più alto o più basso è in parità, solo i giocatori in parità a quell'estremo tirano di nuovo per decidere il vincitore o il perdente di quel lato. I tiri originali più alto e più basso determinano l'importo, anche se uno spareggio cambia l'ordine. Se tutti i giocatori tirano lo stesso numero, nessuno paga e tutti tirano di nuovo.\n\nDEATHROLL\nDopo che l'organizzatore avvia la partita, vengono scelti a caso due giocatori uniti. Scommessa annuncia i giocatori scelti, poi annuncia quale dei due è stato scelto a caso per tirare per primo.\n\nIl primo giocatore tira da 1 al valore totale in argento del piatto. Con un piatto di 10g50s, il primo tiro è da 1 a 1.050. I due giocatori scelti poi si alternano: dopo ogni tiro, il giocatore successivo tira da 1 al valore appena uscito. Usa Annuncia i tiri per indicare di chi è il turno e l'intervallo attuale del tiro. Il primo giocatore che tira 1 perde; l'altro vince il piatto, annunciato nel formato oro e argento.\n\nTERMINARE UNA SESSIONE\nL'organizzatore può selezionare Annulla sessione in qualsiasi momento prima che la sessione sia completata. L'annullamento viene annunciato in chat e la sessione termina per tutti. Le sessioni completate non possono essere annullate.\n\nScommessa annuncia solo i risultati; non trasferisce oro. I giocatori saldano da soli gli importi annunciati."
