L["Add an item ID, drag an item onto its section, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "Aggiungi l'ID di un oggetto, trascina un oggetto sulla sua sezione o importa una lista. Il cibo conta qualsiasi beneficio Ben nutrito, gli altri oggetti il proprio beneficio; aggiungi gli ID degli incantesimi di beneficio solo per un oggetto che ne dà un altro. Nulla viene aggiunto automaticamente. Passa sopra un promemoria per scegliere un oggetto configurato dalle borse. I promemoria si fermano in combattimento; i menu degli oggetti funzionano fuori dal combattimento. Quando e dove appaiono si imposta in AuraBuffs > Impostazioni."
